public Vec3d calculateIntercept(Vec3d origin, Vec3d endpoint, float fuzziness){

	// We want the intercept between the line and a sphere
	// First we need to find the point where the line is closest to the centre
	// Then we can use a bit of geometry to find the intercept

	// Find the closest point to the centre
	// http://mathworld.wolfram.com/Point-LineDistance3-Dimensional.html
	Vec3d line = endpoint.subtract(origin);
	double t = -origin.subtract(this.getPositionVector()).dotProduct(line) / line.lengthSquared();
	Vec3d closestPoint = origin.add(line.scale(t));
	// Now calculate the distance from that point to the centre (squared because that's all we need)
	double dsquared = closestPoint.squareDistanceTo(this.getPositionVector());
	double rsquared = Math.pow(radius + fuzziness, 2);
	// If the minimum distance is outside the radius (plus fuzziness) then there is no intercept
	if(dsquared > rsquared) return null;
	// Now do pythagoras to find the other side of the triangle, which is the distance along the line from
	// the closest point to the edge of the sphere, and go that far back towards the origin - and that's it!
	return closestPoint.subtract(line.normalize().scale(MathHelper.sqrt(rsquared - dsquared)));
}

public static RayTraceResult rayTrace(World world, Vec3d origin, Vec3d endpoint, float aimAssist,
									  boolean hitLiquids, boolean ignoreUncollidables, boolean returnLastUncollidable, Class<? extends Entity> entityType, Predicate<? super Entity> filter){

	// 1 is the standard amount of extra search volume, and aim assist needs to increase this further as well as
	// expanding the entities' bounding boxes.
	float borderSize = 1 + aimAssist;

	// The AxisAlignedBB constructor accepts min/max coords in either order.
	AxisAlignedBB searchVolume = new AxisAlignedBB(origin.x, origin.y, origin.z, endpoint.x, endpoint.y, endpoint.z)
			.grow(borderSize, borderSize, borderSize);

	// Gets all of the entities in the bounding box that could be collided with.
	List<Entity> entities = world.getEntitiesWithinAABB(entityType, searchVolume);
	// Applies the given filter to remove entities that should be ignored.
	entities.removeIf(filter);

	// Finds the first block hit by the ray trace, if any.
	RayTraceResult result = world.rayTraceBlocks(origin, endpoint, hitLiquids, ignoreUncollidables, returnLastUncollidable);

	// Clips the entity search range to the part of the ray trace before the block hit, if it hit a block.
	if(result != null){
		endpoint = result.hitVec;
	}

	// Search variables
	Entity closestHitEntity = null;
	Vec3d closestHitPosition = endpoint;
	AxisAlignedBB entityBounds;
	Vec3d intercept = null;

	// Iterates through all the entities
	for(Entity entity : entities){

		// I'd like to add the following line so we can, for example, use greater telekinesis through a
		// ring of fire, but doing so will stop forcefields blocking particles
		//if(!entity.canBeCollidedWith()) continue;

		float fuzziness = EntityUtils.isLiving(entity) ? aimAssist : 0; // Only living entities have aim assist

		if(entity instanceof ICustomHitbox){ // Custom hitboxes
			intercept = ((ICustomHitbox)entity).calculateIntercept(origin, endpoint, fuzziness);

		}else{ // Normal hit detection

			entityBounds = entity.getEntityBoundingBox();

			if(entityBounds != null){

				// This is zero for everything except fireballs...
				float entityBorderSize = entity.getCollisionBorderSize();
				// ... meaning the following line does nothing in all other cases.
				// -> Added the non-zero check to prevent unnecessary AABB object creation.
				if(entityBorderSize != 0)
					entityBounds = entityBounds.grow(entityBorderSize, entityBorderSize, entityBorderSize);

				// Aim assist expands the bounding box to hit entities within the specified distance of the ray trace.
				if(fuzziness != 0) entityBounds = entityBounds.grow(fuzziness, fuzziness, fuzziness);

				// Finds the first point at which the ray trace intercepts the entity's bounding box, if any.
				RayTraceResult hit = entityBounds.calculateIntercept(origin, endpoint);
				if(hit != null) intercept = hit.hitVec;
			}
		}

		// If the ray trace hit the entity...
		if(intercept != null){
			// Decides whether the entity that was hit is the closest so far, and if so, overwrites the old one.
			float currentHitDistance = (float)intercept.distanceTo(origin);
			float closestHitDistance = (float)closestHitPosition.distanceTo(origin);
			if(currentHitDistance < closestHitDistance){
				closestHitEntity = entity;
				closestHitPosition = intercept;
			}
		}
	}

	// If the ray trace hit an entity, return that entity; otherwise return the result of the block ray trace.
	if(closestHitEntity != null){
		result = new RayTraceResult(closestHitEntity, closestHitPosition);
	}

	return result;
}

protected boolean shootSpell(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){

	double range = getRange(world, origin, direction, caster, ticksInUse, modifiers);
	Vec3d endpoint = origin.add(direction.scale(range));

	// Change the filter depending on whether living entities are ignored or not
	RayTraceResult rayTrace = RayTracer.rayTrace(world, origin, endpoint, aimAssist, hitLiquids,
			ignoreUncollidables, false, Entity.class, ignoreLivingEntities ? EntityUtils::isLiving
			: RayTracer.ignoreEntityFilter(caster));

	boolean flag = false;

	if(rayTrace != null){
		// Doesn't matter which way round these are, they're mutually exclusive
		if(rayTrace.typeOfHit == RayTraceResult.Type.ENTITY){
			// Do whatever the spell does when it hits an entity
			// FIXME: Some spells (e.g. lightning web) seem to not render when aimed at item frames
			flag = onEntityHit(world, rayTrace.entityHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// If the spell succeeded, clip the particles to the correct distance so they don't go through the entity
			if(flag) range = origin.distanceTo(rayTrace.hitVec);

		}else if(rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){
			// Do whatever the spell does when it hits an block
			flag = onBlockHit(world, rayTrace.getBlockPos(), rayTrace.sideHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// Clip the particles to the correct distance so they don't go through the block
			// Unlike with entities, this is done regardless of whether the spell succeeded, since no spells go
			// through blocks (and in fact, even the ray tracer itself doesn't do that)
			range = origin.distanceTo(rayTrace.hitVec);
		}
	}

	// If flag is false, either the spell missed or the relevant entity/block hit method returned false
	if(!flag && !onMiss(world, caster, origin, direction, ticksInUse, modifiers)) return false;

	// Particle spawning
	if(world.isRemote){
		spawnParticleRay(world, origin, direction, caster, range);
	}

	return true;
}

public void onUpdate(){

	super.onUpdate();

	// Projectile disappears after its lifetime (if it has one) has elapsed
	if(getLifetime() >=0 && this.ticksExisted > getLifetime()){
		this.setDead();
	}

	if(this.getCaster() == null && this.casterUUID != null){
		Entity entity = EntityUtils.getEntityByUUID(world, casterUUID);
		if(entity instanceof EntityLivingBase){
			this.caster = new WeakReference<>((EntityLivingBase)entity);
		}
	}

	if(this.prevRotationPitch == 0.0F && this.prevRotationYaw == 0.0F){
		float f = MathHelper.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ);
		this.prevRotationYaw = this.rotationYaw = (float)(Math.atan2(this.motionX, this.motionZ) * 180.0D
				/ Math.PI);
		this.prevRotationPitch = this.rotationPitch = (float)(Math.atan2(this.motionY, (double)f) * 180.0D
				/ Math.PI);
	}

	BlockPos blockpos = new BlockPos(this.blockX, this.blockY, this.blockZ);
	IBlockState iblockstate = this.world.getBlockState(blockpos);

	if(iblockstate.getMaterial() != Material.AIR){
		AxisAlignedBB axisalignedbb = iblockstate.getCollisionBoundingBox(this.world, blockpos);

		if(axisalignedbb != Block.NULL_AABB
				&& axisalignedbb.offset(blockpos).contains(new Vec3d(this.posX, this.posY, this.posZ))){
			this.inGround = true;
		}
	}

	if(this.arrowShake > 0){
		--this.arrowShake;
	}

	// When the arrow is in the ground
	if(this.inGround){
		++this.ticksInGround;
		this.tickInGround();
	}
	// When the arrow is in the air
	else{

		this.tickInAir();

		this.ticksInGround = 0;
		++this.ticksInAir;

		// Does a ray trace to determine whether the projectile will hit a block in the next tick

		Vec3d vec3d1 = new Vec3d(this.posX, this.posY, this.posZ);
		Vec3d vec3d = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
		RayTraceResult raytraceresult = this.world.rayTraceBlocks(vec3d1, vec3d, false, true, false);
		vec3d1 = new Vec3d(this.posX, this.posY, this.posZ);
		vec3d = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);

		if(raytraceresult != null){
			vec3d = new Vec3d(raytraceresult.hitVec.x, raytraceresult.hitVec.y,
					raytraceresult.hitVec.z);
		}

		// Uses bounding boxes to determine whether the projectile will hit an entity in the next tick, and if so
		// overwrites the block hit with an entity

		Entity entity = null;
		List<?> list = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox()
				.expand(this.motionX, this.motionY, this.motionZ).grow(1.0D, 1.0D, 1.0D));
		double d0 = 0.0D;
		int i;
		float f1;

		for(i = 0; i < list.size(); ++i){
			Entity entity1 = (Entity)list.get(i);

			if(entity1.canBeCollidedWith() && (entity1 != this.getCaster() || this.ticksInAir >= 5)){
				f1 = 0.3F;
				AxisAlignedBB axisalignedbb1 = entity1.getEntityBoundingBox().grow((double)f1, (double)f1,
						(double)f1);
				RayTraceResult RayTraceResult1 = axisalignedbb1.calculateIntercept(vec3d1, vec3d);

				if(RayTraceResult1 != null){
					double d1 = vec3d1.distanceTo(RayTraceResult1.hitVec);

					if(d1 < d0 || d0 == 0.0D){
						entity = entity1;
						d0 = d1;
					}
				}
			}
		}

		if(entity != null){
			raytraceresult = new RayTraceResult(entity);
		}

		// Players that are considered invulnerable to the caster allow the projectile to pass straight through
		// them.
		if(raytraceresult != null && raytraceresult.entityHit != null
				&& raytraceresult.entityHit instanceof EntityPlayer){
			EntityPlayer entityplayer = (EntityPlayer)raytraceresult.entityHit;

			if(entityplayer.capabilities.disableDamage || this.getCaster() instanceof EntityPlayer
					&& !((EntityPlayer)this.getCaster()).canAttackPlayer(entityplayer)){
				raytraceresult = null;
			}
		}

		// If the arrow hits something
		if(raytraceresult != null){
			// If the arrow hits an entity
			if(raytraceresult.entityHit != null){
				DamageSource damagesource = null;

				if(this.getCaster() == null){
					damagesource = DamageSource.causeThrownDamage(this, this);
				}else{
					damagesource = MagicDamage.causeIndirectMagicDamage(this, this.getCaster(), this.getDamageType()).setProjectile();
				}

				if(raytraceresult.entityHit.attackEntityFrom(damagesource,
						(float)(this.getDamage() * this.damageMultiplier))){
					if(raytraceresult.entityHit instanceof EntityLivingBase){
						EntityLivingBase entityHit = (EntityLivingBase)raytraceresult.entityHit;

						this.onEntityHit(entityHit);

						if(this.knockbackStrength > 0){
							float f4 = MathHelper.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ);

							if(f4 > 0.0F){
								raytraceresult.entityHit.addVelocity(
										this.motionX * (double)this.knockbackStrength * 0.6000000238418579D
												/ (double)f4,
										0.1D, this.motionZ * (double)this.knockbackStrength * 0.6000000238418579D
												/ (double)f4);
							}
						}

						// Thorns enchantment
						if(this.getCaster() != null){
							EnchantmentHelper.applyThornEnchantments(entityHit, this.getCaster());
							EnchantmentHelper.applyArthropodEnchantments(this.getCaster(), entityHit);
						}

						if(this.getCaster() != null && raytraceresult.entityHit != this.getCaster()
								&& raytraceresult.entityHit instanceof EntityPlayer
								&& this.getCaster() instanceof EntityPlayerMP){
							((EntityPlayerMP)this.getCaster()).connection
									.sendPacket(new SPacketChangeGameState(6, 0.0F));
						}
					}

					if(!(raytraceresult.entityHit instanceof EntityEnderman) && !this.doOverpenetration()){
						this.setDead();
					}
				}else{
					if(!this.doOverpenetration()) this.setDead();

					// Was the 'rebound' that happened when entities were immune to damage
					/* this.motionX *= -0.10000000149011612D; this.motionY *= -0.10000000149011612D; this.motionZ *=
					 * -0.10000000149011612D; this.rotationYaw += 180.0F; this.prevRotationYaw += 180.0F;
					 * this.ticksInAir = 0; */
				}
			}
			// If the arrow hits a block
			else{
				this.blockX = raytraceresult.getBlockPos().getX();
				this.blockY = raytraceresult.getBlockPos().getY();
				this.blockZ = raytraceresult.getBlockPos().getZ();
				this.stuckInBlock = this.world.getBlockState(raytraceresult.getBlockPos());
				this.motionX = (double)((float)(raytraceresult.hitVec.x - this.posX));
				this.motionY = (double)((float)(raytraceresult.hitVec.y - this.posY));
				this.motionZ = (double)((float)(raytraceresult.hitVec.z - this.posZ));
				// f2 = MathHelper.sqrt(this.motionX * this.motionX + this.motionY * this.motionY + this.motionZ *
				// this.motionZ);
				// this.posX -= this.motionX / (double)f2 * 0.05000000074505806D;
				// this.posY -= this.motionY / (double)f2 * 0.05000000074505806D;
				// this.posZ -= this.motionZ / (double)f2 * 0.05000000074505806D;
				// this.playSound("random.bowhit", 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));
				this.inGround = true;
				this.arrowShake = 7;

				this.onBlockHit(raytraceresult);

				if(this.stuckInBlock.getMaterial() != Material.AIR){
					this.stuckInBlock.getBlock().onEntityCollision(this.world, raytraceresult.getBlockPos(),
							this.stuckInBlock, this);
				}
			}
		}

		// Seeking
		if(getSeekingStrength() > 0){

			Vec3d velocity = new Vec3d(motionX, motionY, motionZ);

			RayTraceResult hit = RayTracer.rayTrace(world, this.getPositionVector(),
					this.getPositionVector().add(velocity.scale(SEEKING_TIME)), getSeekingStrength(), false,
					true, false, EntityLivingBase.class, RayTracer.ignoreEntityFilter(null));

			if(hit != null && hit.entityHit != null){

				if(AllyDesignationSystem.isValidTarget(getCaster(), hit.entityHit)){

					Vec3d direction = new Vec3d(hit.entityHit.posX, hit.entityHit.posY + hit.entityHit.height/2,
							hit.entityHit.posZ).subtract(this.getPositionVector()).normalize().scale(velocity.length());

					motionX = motionX + 2 * (direction.x - motionX) / SEEKING_TIME;
					motionY = motionY + 2 * (direction.y - motionY) / SEEKING_TIME;
					motionZ = motionZ + 2 * (direction.z - motionZ) / SEEKING_TIME;
				}
			}
		}

		this.posX += this.motionX;
		this.posY += this.motionY;
		this.posZ += this.motionZ;
		// f2 = MathHelper.sqrt(this.motionX * this.motionX + this.motionZ * this.motionZ);
		this.rotationYaw = (float)(Math.atan2(this.motionX, this.motionZ) * 180.0D / Math.PI);

		// for (this.rotationPitch = (float)(Math.atan2(this.motionY, (double)f2) * 180.0D / Math.PI);
		// this.rotationPitch - this.prevRotationPitch < -180.0F; this.prevRotationPitch -= 360.0F)
		// {
		// ;
		// }

		while(this.rotationPitch - this.prevRotationPitch >= 180.0F){
			this.prevRotationPitch += 360.0F;
		}

		while(this.rotationYaw - this.prevRotationYaw < -180.0F){
			this.prevRotationYaw -= 360.0F;
		}

		while(this.rotationYaw - this.prevRotationYaw >= 180.0F){
			this.prevRotationYaw += 360.0F;
		}

		this.rotationPitch = this.prevRotationPitch + (this.rotationPitch - this.prevRotationPitch) * 0.2F;
		this.rotationYaw = this.prevRotationYaw + (this.rotationYaw - this.prevRotationYaw) * 0.2F;

		float f3 = 0.99F;

		if(this.isInWater()){
			for(int l = 0; l < 4; ++l){
				float f4 = 0.25F;
				this.world.spawnParticle(EnumParticleTypes.WATER_BUBBLE, this.posX - this.motionX * (double)f4,
						this.posY - this.motionY * (double)f4, this.posZ - this.motionZ * (double)f4, this.motionX,
						this.motionY, this.motionZ);
			}

			f3 = 0.8F;
		}

		if(this.isWet()){
			this.extinguish();
		}

		if(this.doDeceleration()){
			this.motionX *= (double)f3;
			this.motionY *= (double)f3;
			this.motionZ *= (double)f3;
		}

		if(this.doGravity()) this.motionY -= 0.05;

		this.setPosition(this.posX, this.posY, this.posZ);
		this.doBlockCollisions();
	}
}

